/// <summary>Ikona kategórie: biely symbol na farebnom štvorčeku (v evidencii, v číselníku a v tlačových zostavách).</summary>
public sealed class IkonaKategorie
{
    public IkonaKategorie(string kluc, string nazov, string farba, int mierka, string[] klucoveSlova, string subor, string cesta)
    {
        Kluc = kluc;
        NazovSk = nazov;
        PredvolenaFarba = farba;
        Mierka = mierka;
        KlucoveSlova = klucoveSlova;
        Subor = subor;
        Cesta = cesta;
        Geometria = Geometry.Parse("F1 " + cesta);
        Geometria.Freeze();
    }

    public string Kluc { get; }
    private string NazovSk { get; }
    public string Nazov => Preklad.T(NazovSk);
    public string PredvolenaFarba { get; }

    /// <summary>Rozmer kresby ikony (20 alebo 16 bodov) – na prepočet do ľubovoľnej veľkosti.</summary>
    public int Mierka { get; }

    /// <summary>Slová v názve kategórie (bez diakritiky, malými), podľa ktorých sa ikona priradí automaticky.</summary>
    public string[] KlucoveSlova { get; }

    /// <summary>Pôvodný súbor zo sady Fluent UI System Icons (Microsoft, licencia MIT).</summary>
    public string Subor { get; }
    public string Cesta { get; }
    public Geometry Geometria { get; }

    /// <summary>Ikona s konkrétnou farbou (kategória môže mať vlastnú farbu).</summary>
    public FarebnaIkona SFarbou(string? farba) => new(this, IkonyKategorii.PlatnaFarba(farba) ?? PredvolenaFarba);
}

/// <summary>Ikona kategórie s farbou – na zobrazenie (štvorček s bielym symbolom).</summary>
public sealed class FarebnaIkona
{
    public FarebnaIkona(IkonaKategorie ikona, string farba)
    {
        Ikona = ikona;
        Farba = farba;
        var stetec = new SolidColorBrush((Color)ColorConverter.ConvertFromString(farba));
        stetec.Freeze();
        Stetec = stetec;
    }

    public IkonaKategorie Ikona { get; }
    public string Farba { get; }
    public Brush Stetec { get; }
    public Geometry Geometria => Ikona.Geometria;
    public string Nazov => Ikona.Nazov;
}

