    private static readonly Dictionary<string, IkonaKategorie> PodlaKluca = Vsetky.ToDictionary(i => i.Kluc);

    public static IkonaKategorie Podla(string? kluc) =>
        kluc is not null && PodlaKluca.TryGetValue(kluc, out var ikona) ? ikona : PodlaKluca[Predvolena];

    /// <summary>Platná farba #RRGGBB, inak null.</summary>
    public static string? PlatnaFarba(string? farba) =>
        farba is not null && Regex.IsMatch(farba, "^#[0-9A-Fa-f]{6}$") ? farba.ToUpperInvariant() : null;

    /// <summary>
    /// Ikona podľa názvu kategórie („notebook“ → notebook, „Multifunkčná tlačiareň“ → multifunkcia). Vyhráva najdlhšie
    /// zhodné kľúčové slovo; krátke slová (do 3 znakov) musia byť celé slovo. Ak nič nesedí, ikona „Iné“.
    /// </summary>
    /// <summary>Počiatočné kategórie (slovenský kľúč prekladu) – spoľahlivé priradenie aj v inom jazyku programu.</summary>
    private static readonly (string Kategoria, string Ikona)[] Pociatocne =
    {
        ("All-in-One", "aio"), ("interaktívna tabuľa", "tabula"), ("kopírka", "kopirka"), ("multiboard", "multiboard"),
        ("multifunkcia", "multifunkcia"), ("notebook", "notebook"), ("PC", "pc"), ("príslušenstvo", "prislusenstvo"),
        ("projektor", "projektor"), ("router", "router"), ("skener", "skener"), ("slúchadlá", "sluchadla"),
        ("switch", "switch"), ("tablet", "tablet"), ("tlačiareň", "tlaciaren"),
    };

    public static IkonaKategorie PodlaNazvu(string? nazov)
    {
        if (string.IsNullOrWhiteSpace(nazov))
        {
            return PodlaKluca[Predvolena];
        }

        foreach (var (kategoria, kluc) in Pociatocne)
        {
            if (nazov.Trim().Equals(Preklad.T(kategoria), StringComparison.CurrentCultureIgnoreCase)
                || nazov.Trim().Equals(kategoria, StringComparison.CurrentCultureIgnoreCase))
            {
                return PodlaKluca[kluc];
            }
        }

        var text = " " + Sk.BezDiakritiky(nazov ?? "").ToLowerInvariant() + " ";
        IkonaKategorie? najlepsia = null;
        var dlzka = 0;
        foreach (var ikona in Vsetky)
        {
            foreach (var slovo in ikona.KlucoveSlova)
            {
                var vzor = slovo.Length <= 3
                    ? @"(?<![\p{L}\p{N}])" + Regex.Escape(slovo) + @"(?![\p{L}\p{N}])"
                    : @"(?<![\p{L}\p{N}])" + Regex.Escape(slovo);
                if (slovo.Length > dlzka && Regex.IsMatch(text, vzor))
                {
                    najlepsia = ikona;
                    dlzka = slovo.Length;
                }
            }
        }

        return najlepsia ?? PodlaKluca[Predvolena];
    }

    /// <summary>Ikona kategórie: zvolená ručne, inak podľa názvu; farba vlastná, inak predvolená farba ikony.</summary>
    public static FarebnaIkona Pre(string? kluc, string? farba, string? nazovKategorie) =>
        (kluc is not null && PodlaKluca.ContainsKey(kluc) ? PodlaKluca[kluc] : PodlaNazvu(nazovKategorie)).SFarbou(farba);

    /// <summary>Ikona ako obrázok PNG (na tlač do PDF): zaoblený farebný štvorček s bielym symbolom.</summary>
    public static byte[] Png(FarebnaIkona ikona, int velkost = 64)
    {
        byte[]? vysledok = null;
        void Kresli()
        {
            var kresba = new DrawingVisual();
            using (var dc = kresba.RenderOpen())
            {
                dc.DrawRoundedRectangle(ikona.Stetec, null, new Rect(0, 0, velkost, velkost), velkost * 0.2, velkost * 0.2);
                var okraj = velkost * 0.18;
                var mierka = (velkost - 2 * okraj) / ikona.Ikona.Mierka;
                dc.PushTransform(new TranslateTransform(okraj, okraj));
                dc.PushTransform(new ScaleTransform(mierka, mierka));
                dc.DrawGeometry(Brushes.White, null, ikona.Geometria);
                dc.Pop();
                dc.Pop();
            }

            var obraz = new RenderTargetBitmap(velkost, velkost, 96, 96, PixelFormats.Pbgra32);
            obraz.Render(kresba);
            var koder = new PngBitmapEncoder();
            koder.Frames.Add(BitmapFrame.Create(obraz));
            using var prud = new MemoryStream();
            koder.Save(prud);
            vysledok = prud.ToArray();
        }

        // kreslenie WPF potrebuje vlákno STA (zostava sa môže tvoriť aj na pozadí)
        if (Thread.CurrentThread.GetApartmentState() == ApartmentState.STA)
        {
            Kresli();
        }
        else
        {
            var vlakno = new Thread(Kresli);
            vlakno.SetApartmentState(ApartmentState.STA);
            vlakno.Start();
            vlakno.Join();
        }

        return vysledok!;
    }
}
